/// <summary>
/// The controller class for the Planner code update batch job.
/// </summary>
class METPlannerCodeUpdController extends SysOperationServiceController
{
}

Method.Source:
    /// <summary>
    /// The new method of the class
    /// </summary>
    public void new()
    {
        super();

        this.parmClassName(classStr(METPlannerCodeUpdService));
        this.parmMethodName(methodStr(METPlannerCodeUpdService, processOperation));        
    }

/// <summary>
/// The caption method of the batch job dialog.
/// </summary>
/// <returns>String value to be used on dialog</returns>
public ClassDescription caption()
{
    return "@MET:METPlannerCodeUpdateBatchJob";
}

/// <summary>
/// The main method of the batch job.
/// </summary>
/// <param name = "_args">The arguments passed by the caller object.</param>
public static void main(Args _args)
{
    SysOperationController controller = new METPlannerCodeUpdController();
    controller.startOperation();
}
